#!/bin/bash
cd "$(dirname "$0")/../.."
PY=.venv/bin/python
B=page2/branding
STYLE="Palette: deep steel navy #14212E, safety orange #FF7A1A, warm off-white #F4F1EA. Professional vector brand design, flat with subtle depth, crisp edges, no gradients mess, no extra text, no watermark."
$PY tools/gen_image.py $B/logo-1.png "Logo for a YouTube/Facebook channel called SELF-MADE ENGINEER about crazy backyard engineering builds. Circular emblem: a bold safety-orange gear with a lightning bolt through its centre and a crossed wrench, on a deep navy circle. Wordmark SELF-MADE ENGINEER curved around the top and bottom of the ring in bold white sans-serif. Must stay legible when shown as a tiny circle. $STYLE" 1:1 &
$PY tools/gen_image.py $B/logo-2.png "Mascot logo for a channel called SELF-MADE ENGINEER: friendly stocky American handyman, about 48, short salt-and-pepper beard, round safety glasses pushed up on his forehead, red bandana around his neck, confident grin, head-and-shoulders inside a deep navy circle with a safety-orange ring. Bold white text SELF-MADE ENGINEER on a curved banner at the bottom. Clean cartoon vector style, legible as a small profile picture. $STYLE" 1:1 &
$PY tools/gen_image.py $B/logo-3.png "Minimal monogram logo for SELF-MADE ENGINEER: large bold letters SME in white heavy sans-serif, the M shaped like a tall wind-turbine tower with a small safety-orange three-blade rotor on top, on a solid deep navy circle with a thin orange outer ring. Under the monogram, small clean text SELF-MADE ENGINEER. Very legible at tiny sizes. $STYLE" 1:1 &
wait
$PY tools/gen_image.py $B/cover-1.png "Facebook cover banner, wide panoramic, for SELF-MADE ENGINEER. Bright sunny stylized 3D render of an American suburban-edge backyard: white two-story house with porch, red pickup in the driveway, wooden workshop barn, creek with a small waterfall, a tall wind turbine on a green ridge, a white goose in the yard. Right two-thirds: bold title SELF-MADE ENGINEER in white heavy sans-serif with a safety-orange underline, tagline 'Crazy backyard builds. Real physics.' Keep the bottom-left corner calm (profile picture overlaps there). $STYLE" 21:9 &
$PY tools/gen_image.py $B/cover-2.png "Wide Facebook cover banner for SELF-MADE ENGINEER: deep navy blueprint background with faint white technical line drawings of a wind turbine, a water wheel, a ram pump and gears; on the right a clean stylized 3D backyard workshop scene in daylight with a wind turbine. Large bold white title SELF-MADE ENGINEER, safety-orange tagline 'Crazy backyard builds. Real physics.' centred-right. Bottom-left corner kept empty. $STYLE" 21:9 &
$PY tools/gen_image.py $B/cover-3.png "Wide Facebook cover banner for SELF-MADE ENGINEER: golden-hour stylized 3D countryside property on a hillside, wind turbine spinning on the ridge, glowing workshop, creek, pickup truck, string lights; bold title SELF-MADE ENGINEER in white with a safety-orange bolt icon, tagline 'Crazy backyard builds. Real physics.' on the right half. Bottom-left corner calm and empty. $STYLE" 21:9 &
wait
ls -la $B
